 Laboratories"},{"icon":"ti-home","name":"Separate Hostels"},{"icon":"ti-bus","name":"Transport Facility"},{"icon":"ti-cpu","name":"Innovation & Incubation Centre"},{"icon":"ti-crown","name":"Placement Training Cell"},{"icon":"ti-heartbeat","name":"Medical Support Centre"},{"icon":"ti-trophy","name":"Sports Facilities"},{"icon":"ti-microphone","name":"Seminar Halls"},{"icon":"ti-bolt","name":"Entrepreneurship Cell"},{"icon":"ti-cpu","name":"Smart Classrooms"}],"placementRate":85,"avgPackage":"₹3.2 LPA","highestPackage":"₹7.8 LPA","placementYear":null,"admissionProcess":[{"title":"Apply Through TNEA Counselling","desc":"Register on the official TNEA portal and participate in the counselling process based on 12th standard marks."},{"title":"Document Verification","desc":"Attend verification at designated centres with original academic and identity certificates."},{"title":"Merit-Based Seat Allocation","desc":"Seats are allotted based on TNEA rank, reservation category, and choice filling preferences."},{"title":"Fee Payment Confirmation","desc":"Confirm admission by paying the prescribed fees through the official counselling portal."},{"title":"Reporting to College","desc":"Join the institution on the specified date with all required documents for enrollment."}],"scholarships":["First Graduate Scholarship (Tamil Nadu Government)","BC / MBC Scholarship","SC / ST Scholarship","AICTE Pragati Scholarship","AICTE Saksham Scholarship","Merit-Based Institutional Scholarship","Minority Scholarship","Post Matric Scholarship","Chief Minister Scholarship Scheme","Sports Scholarship for Achievers"],"events":["TECHFEST — National Level Symposium","Hackathon Challenge Series","Project Expo Exhibition","Annual Sports Meet","Cultural Fest — TERASA UTSAV","Entrepreneurship Development Summit"],"distanceInfo":{"airport":"45 km","railway":"18 km","bustand":"6 km","metro":"N/A","hospital":"4 km"},"hostelFeatures":["Separate Boys & Girls Hostels","24x7 Security","Wi-Fi Enabled Campus","Hy