SET NAMES utf8mb4;
SET SESSION sql_mode = 'NO_ENGINE_SUBSTITUTION';
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS colleges (
  id VARCHAR(191) NOT NULL,
  slug VARCHAR(191) NOT NULL,
  name VARCHAR(500) NOT NULL,
  short_name VARCHAR(500) NULL,
  category VARCHAR(100) NULL,
  type VARCHAR(255) NULL,
  ownership VARCHAR(100) NULL,
  established INT NULL,
  location VARCHAR(500) NULL,
  district VARCHAR(150) NULL,
  address TEXT NULL,
  map_link TEXT NULL,
  website TEXT NULL,
  phone VARCHAR(255) NULL,
  email VARCHAR(255) NULL,
  image TEXT NULL,
  meta_title VARCHAR(500) NULL,
  meta_description TEXT NULL,
  canonical_url TEXT NULL,
  data JSON NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_colleges_slug (slug),
  KEY idx_colleges_district (district),
  KEY idx_colleges_category (category),
  KEY idx_colleges_ownership (ownership),
  KEY idx_colleges_established (established)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

